struct Account {
    balance: u32,
}

impl Account {
    fn read(&self) -> u32 {
        self.balance
    }
    fn with_bonus(mut self, bonus: u32) -> Self {
        self.balance += bonus;
        self
    }
    fn change(&mut self) {
        self.balance += 1;
    }
    fn consume(self) -> u32 {
        self.balance
    }
}

